# -*- coding: utf-8 -*-
"""
Interseccion Lotes x Suelos CONEAT + PDF cartografico - ProNutrition v8

QGIS Processing script.
Entrada:
  - capa de lotes (poligonos)
  - capa de Suelos CONEAT (poligonos; por defecto campo SC)
Salida:
  - Shapefile con TODOS los atributos de lotes + SC
  - PDF A4 multipagina, estilo Suelos CONEAT

Instalacion:
  Procesos > Caja de herramientas > Scripts > Anadir script a la caja de herramientas.
"""

import os
import math
import tempfile
import shutil
import base64
import zlib
import json
from collections import defaultdict

from qgis.PyQt.QtCore import QCoreApplication
from qgis.core import (
    QgsProcessing, QgsProcessingAlgorithm, QgsProcessingException,
    QgsProcessingParameterFeatureSource, QgsProcessingParameterField,
    QgsProcessingParameterFileDestination, QgsProcessingParameterString,
    QgsProcessingParameterFile, QgsProcessingOutputFile,
    QgsVectorLayer, QgsVectorFileWriter, QgsProject, QgsFeatureRequest,
    QgsGeometry, QgsRectangle, QgsCoordinateReferenceSystem,
    QgsCoordinateTransform, QgsWkbTypes
)
import processing


VERDE = "#159b72"
VERDE_OSCURO = "#237d3b"
PALETA = [
    "#e6cf8a", "#38a9df", "#e52bd5", "#43df91", "#64d53f", "#6957c9",
    "#f08a5d", "#8ecae6", "#ffb703", "#90be6d", "#bc6c25", "#b8b8ff",
    "#ef476f", "#06d6a0", "#118ab2", "#ffd166"
]


DESCRIPCIONES_CONEAT_B64 = ''

class InterseccionLotesConeat(QgsProcessingAlgorithm):
    LOTES = "LOTES"
    CONEAT = "CONEAT"
    CAMPO_SC = "CAMPO_SC"
    CAMPO_EST = "CAMPO_EST"
    TITULO_EST = "TITULO_EST"
    LOGO = "LOGO"
    SALIDA_SHP = "SALIDA_SHP"
    SALIDA_PDF = "SALIDA_PDF"

    def tr(self, s):
        return QCoreApplication.translate("InterseccionLotesConeat", s)

    def createInstance(self):
        return InterseccionLotesConeat()

    def name(self):
        return "interseccion_lotes_coneat_pdf"

    def displayName(self):
        return self.tr("Lotes x CONEAT + PDF")

    def group(self):
        return self.tr("ProNutrition")

    def groupId(self):
        return "pronutrition"

    def shortHelpString(self):
        return self.tr(
            "Intersecta una capa de lotes con Suelos CONEAT. Conserva todos los campos "
            "de lotes y agrega el campo SC. Genera un shapefile y un PDF A4 con mapa, "
            "etiquetas SC, tabla de hectareas por lote y suelo, leyenda, norte, escala y mapa de ubicacion de Uruguay."
        )

    def initAlgorithm(self, config=None):
        self.addParameter(QgsProcessingParameterFeatureSource(
            self.LOTES, self.tr("Capa de lotes"), [QgsProcessing.TypeVectorPolygon]))
        self.addParameter(QgsProcessingParameterFeatureSource(
            self.CONEAT, self.tr("Mapa de Suelos CONEAT"), [QgsProcessing.TypeVectorPolygon]))
        self.addParameter(QgsProcessingParameterField(
            self.CAMPO_SC, self.tr("Campo de suelo CONEAT"), parentLayerParameterName=self.CONEAT,
            type=QgsProcessingParameterField.Any, defaultValue="SC"))
        p = QgsProcessingParameterField(
            self.CAMPO_EST, self.tr("Campo de establecimiento/cliente (opcional)"),
            parentLayerParameterName=self.LOTES, type=QgsProcessingParameterField.Any,
            optional=True)
        self.addParameter(p)
        self.addParameter(QgsProcessingParameterString(
            self.TITULO_EST, self.tr("Nombre de establecimiento (si no se elige campo)"),
            defaultValue="Establecimiento", optional=True))
        self.addParameter(QgsProcessingParameterFile(
            self.LOGO, self.tr("Logo para el PDF (PNG/JPG, opcional)"),
            behavior=QgsProcessingParameterFile.File, fileFilter="Imagen (*.png *.jpg *.jpeg)", optional=True))
        self.addParameter(QgsProcessingParameterFileDestination(
            self.SALIDA_SHP, self.tr("Shapefile Lotes x CONEAT"), "Shapefile (*.shp)"))
        self.addParameter(QgsProcessingParameterFileDestination(
            self.SALIDA_PDF, self.tr("PDF Suelos CONEAT"), "PDF (*.pdf)"))
        self.addOutput(QgsProcessingOutputFile(self.SALIDA_SHP, self.tr("Shapefile resultante")))
        self.addOutput(QgsProcessingOutputFile(self.SALIDA_PDF, self.tr("PDF resultante")))

    def processAlgorithm(self, parameters, context, feedback):
        lotes = self.parameterAsSource(parameters, self.LOTES, context)
        coneat = self.parameterAsSource(parameters, self.CONEAT, context)
        if lotes is None or coneat is None:
            raise QgsProcessingException("No se pudieron abrir las capas de entrada.")

        campo_sc = self.parameterAsString(parameters, self.CAMPO_SC, context) or "SC"
        campo_est = self.parameterAsString(parameters, self.CAMPO_EST, context) or ""
        titulo_est = self.parameterAsString(parameters, self.TITULO_EST, context) or "Establecimiento"
        logo = self.parameterAsFile(parameters, self.LOGO, context) or ""
        out_shp = self.parameterAsFileOutput(parameters, self.SALIDA_SHP, context)
        out_pdf = self.parameterAsFileOutput(parameters, self.SALIDA_PDF, context)

        campos_lotes = [f.name() for f in lotes.fields()]
        campos_coneat = [f.name() for f in coneat.fields()]
        if campo_sc not in campos_coneat:
            # tolerancia a mayusculas/minusculas
            m = {x.lower(): x for x in campos_coneat}
            if campo_sc.lower() in m:
                campo_sc = m[campo_sc.lower()]
            else:
                raise QgsProcessingException(
                    "No existe el campo '{}' en CONEAT. Campos: {}".format(campo_sc, ", ".join(campos_coneat)))
        if campo_est and campo_est not in campos_lotes:
            m = {x.lower(): x for x in campos_lotes}
            campo_est = m.get(campo_est.lower(), "")

        feedback.pushInfo("Lotes: {} entidades".format(lotes.featureCount()))
        feedback.pushInfo("CONEAT: {} entidades".format(coneat.featureCount()))
        if lotes.featureCount() == 0 or coneat.featureCount() == 0:
            raise QgsProcessingException("La capa de lotes o CONEAT no contiene entidades. Revise la entrada.")
        feedback.pushInfo("SRC lotes: {}".format(lotes.sourceCrs().authid()))
        feedback.pushInfo("SRC CONEAT: {}".format(coneat.sourceCrs().authid()))

        # QGIS native:intersection reproyecta el overlay al SRC de entrada cuando corresponde.
        tmp = os.path.join(tempfile.mkdtemp(prefix="coneat_"), "inter.gpkg")
        res = processing.run("native:intersection", {
            "INPUT": parameters[self.LOTES],
            "OVERLAY": parameters[self.CONEAT],
            "INPUT_FIELDS": campos_lotes,
            "OVERLAY_FIELDS": [campo_sc],
            "OVERLAY_FIELDS_PREFIX": "",
            "GRID_SIZE": None,
            "OUTPUT": tmp
        }, context=context, feedback=feedback, is_child_algorithm=True)

        vl = QgsVectorLayer(res["OUTPUT"], "Lotes_CONEAT", "ogr")
        if not vl.isValid():
            raise QgsProcessingException("La interseccion no genero una capa valida.")

        # Resolver nombre final del campo SC por si QGIS tuvo que renombrarlo.
        final_fields = [f.name() for f in vl.fields()]
        sc_final = campo_sc if campo_sc in final_fields else None
        if sc_final is None:
            candidatos = [x for x in final_fields if x.lower().startswith(campo_sc.lower())]
            if not candidatos:
                raise QgsProcessingException("No encuentro el campo SC en la interseccion.")
            sc_final = candidatos[-1]

        # Guardar como shapefile individual (no como carpeta).
        # En Windows/OGR un .shp puede ser interpretado como directorio si existe
        # una salida previa incompatible. Se escribe primero en una carpeta
        # temporal y luego se trasladan los componentes al destino elegido.
        out_shp = os.path.normpath(out_shp)
        if not out_shp.lower().endswith(".shp"):
            out_shp += ".shp"
        destino = os.path.dirname(out_shp) or os.getcwd()
        if os.path.isdir(out_shp):
            raise QgsProcessingException(
                "La salida elegida es una CARPETA llamada '{}'. "
                "Elegí un nombre de archivo .shp distinto o renombrá esa carpeta.".format(out_shp))
        os.makedirs(destino, exist_ok=True)
        feedback.pushInfo("Guardando shapefile: {}".format(out_shp))
        with tempfile.TemporaryDirectory(prefix="coneat_export_") as tmp_export:
            shp_temporal = os.path.join(tmp_export, "resultado.shp")
            opts = QgsVectorFileWriter.SaveVectorOptions()
            opts.driverName = "ESRI Shapefile"
            opts.fileEncoding = "UTF-8"
            opts.actionOnExistingFile = QgsVectorFileWriter.CreateOrOverwriteFile
            err, msg, newfile, newlayer = QgsVectorFileWriter.writeAsVectorFormatV3(
                vl, shp_temporal, context.transformContext(), opts)
            if err != QgsVectorFileWriter.NoError:
                raise QgsProcessingException("Error creando shapefile temporal: {}".format(msg))
            base_dest = os.path.splitext(out_shp)[0]
            # Eliminar únicamente los componentes existentes del mismo shapefile.
            for ext in (".shp", ".shx", ".dbf", ".prj", ".cpg", ".qix"):
                previo = base_dest + ext
                if os.path.isfile(previo):
                    try:
                        os.remove(previo)
                    except OSError as e:
                        raise QgsProcessingException("No se puede reemplazar {}: {}".format(previo, e))
            for nombre in os.listdir(tmp_export):
                origen = os.path.join(tmp_export, nombre)
                ext = os.path.splitext(nombre)[1]
                shutil.move(origen, base_dest + ext)

        final = QgsVectorLayer(out_shp, "Lotes_CONEAT", "ogr")
        if not final.isValid():
            raise QgsProcessingException("No se pudo reabrir el shapefile final.")

        if final.featureCount() == 0:
            raise QgsProcessingException("La interseccion no contiene poligonos; no se puede generar el PDF.")

        # Control de superficie: interseccion vs lotes (en SRC proyectado).
        area_lotes = sum(f.geometry().area() for f in lotes.getFeatures())
        area_out = sum(f.geometry().area() for f in final.getFeatures())
        if area_lotes > 0:
            dif = 100.0 * (area_out - area_lotes) / area_lotes
            feedback.pushInfo("Superficie lotes: {:.2f} ha".format(area_lotes / 10000.0))
            feedback.pushInfo("Superficie intersectada: {:.2f} ha ({:+.3f}%)".format(area_out / 10000.0, dif))
            if abs(dif) > 0.5:
                feedback.pushWarning(
                    "La superficie resultante difiere mas de 0,5%. Puede haber huecos o solapes en CONEAT.")

        self._crear_pdf(final, sc_final, campo_est, titulo_est, logo, out_pdf, context, feedback)
        feedback.pushInfo("OK: {}".format(out_shp))
        feedback.pushInfo("OK: {}".format(out_pdf))
        return {self.SALIDA_SHP: out_shp, self.SALIDA_PDF: out_pdf}

    # ---------------------------------------------------------------- PDF
    def _crear_pdf(self, layer, campo_sc, campo_est, titulo_est, logo, out_pdf, context, feedback):
        try:
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_pdf import PdfPages
            from matplotlib.backends.backend_agg import FigureCanvasAgg
            from matplotlib.patches import Polygon as MplPolygon, Rectangle, Patch
            from matplotlib.collections import PatchCollection
            import matplotlib.patheffects as pe
            from matplotlib import image as mimage
        except Exception as e:
            raise QgsProcessingException("Matplotlib no esta disponible en Python de QGIS: {}".format(e))

        # agrupar por establecimiento; si no hay campo, todo junto
        grupos = defaultdict(list)
        for f in layer.getFeatures():
            est = str(f[campo_est]).strip() if campo_est and campo_est in layer.fields().names() else titulo_est
            if not est or est in ("NULL", "None"):
                est = titulo_est
            grupos[est].append(f)

        os.makedirs(os.path.dirname(out_pdf) or ".", exist_ok=True)
        with PdfPages(out_pdf) as pdf:
            for est, feats in sorted(grupos.items(), key=lambda x: x[0]):
                # Una unica pagina cartografica por establecimiento, sin separar sectores.
                self._pagina_pdf(pdf, Figure, FigureCanvasAgg, MplPolygon, Rectangle, Patch,
                                 PatchCollection, pe, mimage, layer, campo_sc, est, feats, logo,
                                 1, 1, context, feedback, feats_establecimiento=feats)
                # Anexo descriptivo a partir del documento CONEAT proporcionado.
                codigos = sorted({str(f[campo_sc]).strip() for f in feats}, key=self._orden_sc)
                self._paginas_descripcion(pdf, Figure, FigureCanvasAgg, est, codigos, feedback)

    def _paginas_descripcion(self, pdf, Figure, FigureCanvasAgg, est, codigos, feedback):
        import textwrap
        descripciones = json.loads(zlib.decompress(base64.b64decode(DESCRIPCIONES_CONEAT_B64)).decode("utf-8"))
        def normalizar(c):
            c = str(c).strip()
            if c in descripciones:
                return c
            # 03.3 / 3.30: no igualar numeros distintos; solo ceros iniciales en parte entera
            for k in descripciones:
                if k.lower() == c.lower():
                    return k
                if k.split(".")[0].lstrip("0") == c.split(".")[0].lstrip("0") and k.split(".")[-1] == c.split(".")[-1]:
                    return k
            return None
        # Una descripcion por grupo, paginada sin cortar texto.
        contenido = []
        for c in codigos:
            k = normalizar(c)
            if k is None:
                feedback.pushWarning("Sin descripcion en el documento para grupo CONEAT: {}".format(c))
                texto = "No se encontro una descripcion de este grupo en el PDF de referencia."
            else:
                texto = descripciones[k]
            contenido.append((c, texto))
        pagina = []
        # Cada linea ocupa ~0.020 de altura de pagina, caben 37.
        def guardar(lineas):
            if not lineas: return
            fig = Figure(figsize=(8.27, 11.69)); FigureCanvasAgg(fig)
            fig.add_artist(__import__('matplotlib').patches.Rectangle((.045,.035),.91,.93,
                           transform=fig.transFigure, fill=False, lw=1.2, edgecolor='#444444'))
            fig.text(.08,.928,'DESCRIPCION DE GRUPOS CONEAT',color=VERDE_OSCURO,
                     fontsize=15,weight='bold',va='top')
            fig.text(.08,.895,'Establecimiento {}'.format(est),fontsize=10,va='top')
            y=.85
            for tipo,t in lineas:
                if tipo=='titulo':
                    fig.text(.08,y,'Grupo CONEAT '+t,fontsize=12,weight='bold',color=VERDE_OSCURO,va='top')
                    y-=.031
                elif tipo=='vacio': y-=.014
                else:
                    fig.text(.08,y,t,fontsize=9.1,va='top'); y-=.0205
            fig.text(.08,.052,'Fuente: Descripcion_grupos_coneat.pdf',fontsize=7,color='#777777')
            pdf.savefig(fig,dpi=200)
        # Altura aproximada: caben 35 lineas de texto, con encabezados.
        usado=0
        for codigo,desc in contenido:
            lineas=textwrap.wrap(desc,width=100,break_long_words=False,break_on_hyphens=False)
            if usado>0 and usado+min(len(lineas),8)+3>35:
                guardar(pagina); pagina=[]; usado=0
            pagina.append(('titulo',codigo)); usado+=2
            for linea in lineas:
                if usado>=35:
                    guardar(pagina); pagina=[]; usado=0
                pagina.append(('texto',linea)); usado+=1
            pagina.append(('vacio','')); usado+=1
        guardar(pagina)

    def _grupos_espaciales(self, feats):
        """Agrupa sectores alejados para evitar mapas con mucho espacio vacio.
        Dos piezas quedan juntas si sus cajas, ampliadas 350 m, se tocan. Luego fusiona
        grupos pequenos hasta un maximo razonable. Funciona bien para establecimientos fragmentados.
        """
        if len(feats) <= 1:
            return [feats]
        pad = 350.0
        boxes = []
        for f in feats:
            r = f.geometry().boundingBox()
            boxes.append(QgsRectangle(r.xMinimum()-pad, r.yMinimum()-pad, r.xMaximum()+pad, r.yMaximum()+pad))
        parent = list(range(len(feats)))
        def root(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        def union(a,b):
            a,b=root(a),root(b)
            if a!=b: parent[b]=a
        for i in range(len(feats)):
            for j in range(i+1, len(feats)):
                if boxes[i].intersects(boxes[j]):
                    union(i,j)
        d=defaultdict(list)
        for i,f in enumerate(feats): d[root(i)].append(f)
        grupos=list(d.values())
        # Si genera demasiadas paginas, usar una sola; prioriza un informe compacto.
        return grupos if 1 < len(grupos) <= 6 else [feats]

    def _pagina_pdf(self, pdf, Figure, FigureCanvasAgg, MplPolygon, Rectangle, Patch,
                    PatchCollection, pe, mimage, layer, campo_sc, est, feats, logo,
                    ip, npag, context, feedback, feats_establecimiento=None):
        W, H = 8.27, 11.69
        fig = Figure(figsize=(W, H))
        FigureCanvasAgg(fig)
        fig.add_artist(Rectangle((0.025, 0.02), 0.95, 0.955, transform=fig.transFigure,
                                 fill=False, lw=1.8, edgecolor="black"))

        # Marcos cartograficos segun el modelo El Cardo.
        # Se dibujan en coordenadas relativas a la hoja, sin alterar mapas ni datos.
        # Recuadro del mapa de ubicacion (Uruguay).
        fig.add_artist(Rectangle((0.065, 0.845), 0.235, 0.115,
                                 transform=fig.transFigure, fill=False,
                                 edgecolor="black", lw=0.85, zorder=30))
        # Marco interior completo: laterales y bordes superior e inferior.
        # Incluye el mapa principal y el sector inferior (tabla, leyenda, escala y logo).
        from matplotlib.lines import Line2D
        for xa, ya, xb, yb in ((0.045, 0.835, 0.955, 0.835),
                               (0.045, 0.835, 0.045, 0.030),
                               (0.955, 0.835, 0.955, 0.030),
                               (0.045, 0.030, 0.955, 0.030)):
            fig.add_artist(Line2D((xa, xb), (ya, yb),
                                  transform=fig.transFigure,
                                  color="#333333", lw=0.65, zorder=2))

        # Titulo
        fig.add_artist(Rectangle((0.34, 0.855), 0.61, 0.105, transform=fig.transFigure,
                                 fill=False, lw=1.0, edgecolor="#555555"))
        fig.text(0.645, 0.913, "Suelos coneat\nEstablecimiento {}".format(est),
                 ha="center", va="center", fontsize=15, color=VERDE, linespacing=1.25)
        if npag > 1:
            fig.text(0.93, 0.84, "{}/{}".format(ip, npag), ha="right", fontsize=7, color="#666666")

        # Mapa principal
        ax = fig.add_axes([0.055, 0.325, 0.89, 0.505])
        ax.set_axis_off()
        ext = QgsRectangle()
        first = True
        for f in feats:
            r=f.geometry().boundingBox()
            if first: ext=QgsRectangle(r); first=False
            else: ext.combineExtentWith(r)
        dx=max(ext.width(), 1.0); dy=max(ext.height(),1.0)
        cx=(ext.xMinimum()+ext.xMaximum())/2; cy=(ext.yMinimum()+ext.yMaximum())/2
        # mantener aspecto del marco
        frame_ratio=(0.89*W)/(0.505*H)
        data_ratio=dx/dy
        if data_ratio > frame_ratio:
            dy2=dx/frame_ratio
            x0,x1=ext.xMinimum()-dx*.06, ext.xMaximum()+dx*.06
            y0,y1=cy-dy2*.56, cy+dy2*.56
        else:
            dx2=dy*frame_ratio
            x0,x1=cx-dx2*.56, cx+dx2*.56
            y0,y1=ext.yMinimum()-dy*.06, ext.yMaximum()+dy*.06
        ax.set_xlim(x0,x1); ax.set_ylim(y0,y1); ax.set_aspect("equal")

        valores=sorted({str(f[campo_sc]).strip() for f in feats}, key=self._orden_sc)
        colores={v:PALETA[i % len(PALETA)] for i,v in enumerate(valores)}
        halo=[pe.withStroke(linewidth=2.5, foreground="white")]

        for f in feats:
            val=str(f[campo_sc]).strip()
            geom=f.geometry()
            for pol in self._poligonos_qgis(geom):
                ext_ring=[(p.x(),p.y()) for p in pol[0]]
                patch=MplPolygon(ext_ring, closed=True, facecolor=colores[val], edgecolor="#333333", linewidth=.65)
                ax.add_patch(patch)
                # huecos en blanco
                for ring in pol[1:]:
                    xy=[(p.x(),p.y()) for p in ring]
                    ax.add_patch(MplPolygon(xy, closed=True, facecolor="white", edgecolor="#333333", linewidth=.4))
            try:
                pt=geom.pointOnSurface().asPoint()
                ax.text(pt.x(), pt.y(), val, ha="center", va="center", fontsize=8.2,
                        color="#444444", path_effects=halo, zorder=10)
            except Exception:
                pass

        # Norte
        ax.annotate("N", xy=(0.93,0.98), xytext=(0.93,0.87), xycoords="axes fraction",
                    ha="center", va="center", fontsize=12, weight="bold",
                    arrowprops=dict(facecolor="black", edgecolor="black", width=3, headwidth=13))

        # Tabla resumen (equivalente a tabla dinamica): lote > SC > hectareas.
        # Usar todas las entidades del establecimiento en cada pagina, aun cuando
        # el mapa se haya dividido por sectores espaciales.
        todos = feats_establecimiento if feats_establecimiento is not None else feats
        filas_tabla = self._resumen_ha(todos, campo_sc, layer.crs())
        self._dibujar_tabla_ha(fig, Rectangle, filas_tabla, pdf, Figure, FigureCanvasAgg)

        # Escala grafica: posicion fija en el pie, entre tabla y logo.
        ancho = x1 - x0
        escala = self._escala_bonita(ancho * .18)
        ancho_fig = .89 * escala / ancho
        sx = .635 - ancho_fig / 2
        sy = .060
        h = .009
        for k in range(2):
            fig.add_artist(Rectangle((sx + k * ancho_fig / 2, sy), ancho_fig / 2, h,
                                     transform=fig.transFigure,
                                     facecolor="black" if k == 0 else "white",
                                     edgecolor="black", lw=.8, zorder=20))
        for x, etiqueta in ((sx, "0"), (sx + ancho_fig/2, self._fmt_m(escala/2)),
                            (sx + ancho_fig, self._fmt_m(escala) + " m")):
            fig.text(x, sy + h + .006, etiqueta, ha="center", va="bottom",
                     fontsize=8.5, zorder=20)

        # Leyenda a la derecha de la tabla, sin superponerse a la escala.
        fig.text(0.53, 0.268, "Referencias", fontsize=11)
        fig.text(0.53, 0.245, "Suelos coneat", fontsize=8.5)
        xleg, yleg = .53, .220
        for i, v in enumerate(valores):
            col, row = i // 7, i % 7
            xx, yy = xleg + col * .13, yleg - row * .020
            fig.add_artist(Rectangle((xx, yy), .021, .011, transform=fig.transFigure,
                                     facecolor=colores[v], edgecolor="#555", lw=.6))
            fig.text(xx + .027, yy + .001, v, fontsize=7.7, va="bottom")

        # Mapa de Uruguay: capa departamental del proyecto o geometria incorporada.
        axi=fig.add_axes([0.065,0.845,0.235,0.115]); axi.set_axis_off()
        deptos=[]
        crs4326=QgsCoordinateReferenceSystem("EPSG:4326")
        for candidata in QgsProject.instance().mapLayers().values():
            if not isinstance(candidata,QgsVectorLayer) or not candidata.isValid():
                continue
            if candidata.geometryType()!=QgsWkbTypes.PolygonGeometry:
                continue
            nombre=candidata.name().lower()
            if not any(t in nombre for t in ("departament", "depto", "uruguay")):
                continue
            if candidata.featureCount()<18 or candidata.featureCount()>25:
                continue
            try:
                trans=QgsCoordinateTransform(candidata.crs(),crs4326,QgsProject.instance())
                piezas=[]
                for feat in candidata.getFeatures():
                    geom=QgsGeometry(feat.geometry())
                    geom.transform(trans)
                    for pol in self._poligonos_qgis(geom):
                        piezas.append([(pt.x(),pt.y()) for pt in pol[0]])
                if len(piezas)>=19:
                    deptos=piezas
                    break
            except Exception:
                continue
        if not deptos:
            deptos=json.loads(zlib.decompress(base64.b64decode("".join(UY_DEPTOS_B64.split()))).decode("ascii"))
        for pol in deptos:
            axi.add_patch(MplPolygon(pol,closed=True,facecolor="#3aaa35",edgecolor="#222",lw=.55))
        axi.set_xlim(-58.8,-52.8); axi.set_ylim(-35.4,-29.7); axi.set_aspect("equal")
        try:
            tr=QgsCoordinateTransform(layer.crs(),crs4326,context.transformContext())
            p=tr.transform(cx,cy)
            from matplotlib.patches import Rectangle as MplRectangle
            axi.add_patch(MplRectangle((p.x()-.15,p.y()-.12),.30,.24,fill=False,edgecolor="black",lw=1.3))
        except Exception:
            pass

        # Logo
        if logo and os.path.exists(logo):
            try:
                axg=fig.add_axes([.81,.045,.13,.075]); axg.set_axis_off()
                axg.imshow(mimage.imread(logo)); axg.set_aspect("equal")
            except Exception:
                pass
        else:
            fig.text(.87,.075,"PRONUTRITION",ha="center",fontsize=11,weight="bold",color=VERDE_OSCURO)
            fig.text(.87,.058,"Agrotecnologias",ha="center",fontsize=6.5,color="#777777")

        pdf.savefig(fig, dpi=300)
        if len(filas_tabla) > 14:
            self._paginas_tabla_extra(pdf, Figure, FigureCanvasAgg, Rectangle, filas_tabla)

    @staticmethod
    def _resumen_ha(feats, campo_sc, crs):
        """Agrupa area geometrica por Lote/SC (no suma el campo Sup repetido)."""
        from qgis.core import QgsDistanceArea
        calc = QgsDistanceArea()
        calc.setSourceCrs(crs, QgsProject.instance().transformContext())
        calc.setEllipsoid(crs.ellipsoidAcronym() or "WGS84")
        suma = defaultdict(float)
        for f in feats:
            nombres = f.fields().names()
            col_lote = next((c for c in nombres if c.lower() == "lote"), None)
            lote = str(f[col_lote]).strip() if col_lote else "Sin lote"
            suelo = str(f[campo_sc]).strip()
            try:
                area = calc.measureArea(f.geometry()) / 10000.0
            except Exception:
                area = f.geometry().area() / 10000.0
            if area > 0:
                suma[(lote, suelo)] += area
        grupos = defaultdict(list)
        for (lote, suelo), ha in suma.items():
            grupos[lote].append((suelo, ha))
        filas = []
        for lote in sorted(grupos, key=str.casefold):
            partes = sorted(grupos[lote], key=lambda x: InterseccionLotesConeat._orden_sc(x[0]))
            filas.append((lote, sum(ha for _, ha in partes), "lote"))
            for suelo, ha in partes:
                filas.append(("    " + suelo, ha, "suelo"))
        filas.append(("Total", sum(suma.values()), "total"))
        return filas

    @staticmethod
    def _fmt_ha(v):
        return ("{:,.2f}".format(v).replace(",", "X").replace(".", ",").replace("X", "."))

    def _dibujar_tabla_ha(self, fig, Rectangle, filas, pdf, Figure, FigureCanvasAgg):
        """Tabla inferior izquierda; si excede el espacio, continua en pagina adicional."""
        max_filas = 14
        principales = filas[:max_filas]
        # Tabla compacta, conservando su anclaje inferior izquierdo.
        self._tabla_en_fig(fig, Rectangle, principales, .065, .055, .345, .185)

    def _paginas_tabla_extra(self, pdf, Figure, FigureCanvasAgg, Rectangle, filas):
        # La tabla completa se muestra en paginas posteriores si no cabe en el pie.
        for inicio in range(0, len(filas), 42):
            otra = Figure(figsize=(8.27, 11.69))
            FigureCanvasAgg(otra)
            otra.text(.08, .94, "Superficie por lote y grupo CONEAT", fontsize=15,
                      color=VERDE, weight="bold")
            self._tabla_en_fig(otra, Rectangle, filas[inicio:inicio+42], .08, .10, .84, .80)
            pdf.savefig(otra, dpi=300)

    def _tabla_en_fig(self, fig, Rectangle, filas, x, y, w, h):
        ax = fig.add_axes([x, y, w, h])
        ax.set_xlim(0, 1); ax.set_ylim(0, 1); ax.axis("off")
        n = len(filas) + 1
        rh = 1.0 / max(n, 1)
        xsep = .70
        fs = 6.0 if n <= 15 else 7.0
        for i in range(n):
            y0 = 1 - (i + 1) * rh
            if i == 0:
                fondo = "#b6e5a0"
                nom, valor, estilo = "Lotes / Grupo Coneat", "Hectáreas", "cabecera"
            else:
                nom, area, estilo = filas[i-1]
                valor = self._fmt_ha(area)
                fondo = "#b6e5a0" if estilo == "total" else ("#edf7e9" if estilo == "lote" else "white")
            ax.add_patch(Rectangle((0, y0), 1, rh, facecolor=fondo,
                                   edgecolor="#c5c5c5", linewidth=.35))
            ax.text(.018, y0 + rh/2, nom, ha="left", va="center", fontsize=fs,
                    weight="bold" if estilo != "suelo" else "normal")
            ax.text(.985, y0 + rh/2, valor, ha="right", va="center", fontsize=fs,
                    weight="bold" if estilo != "suelo" else "normal")
        ax.plot([xsep, xsep], [0, 1], color="#bcbcbc", lw=.5)

    @staticmethod
    def _poligonos_qgis(geom):
        if geom.isEmpty(): return []
        if QgsWkbTypes.isMultiType(geom.wkbType()):
            return geom.asMultiPolygon()
        p=geom.asPolygon()
        return [p] if p else []

    @staticmethod
    def _orden_sc(v):
        try:
            base="".join(c for c in v if c.isdigit() or c==".")
            suf=v[len(base):]
            return (float(base),suf)
        except Exception:
            return (999999.0,v)

    @staticmethod
    def _escala_bonita(v):
        if v <= 0: return 100
        e=10**math.floor(math.log10(v))
        n=v/e
        m=1 if n<1.5 else 2 if n<3.5 else 5 if n<7.5 else 10
        return m*e

    @staticmethod
    def _fmt_m(v):
        return str(int(round(v)))


